import api from './api';

const AuthService = {
  login: async (credentials) => {
    const response = await api.post('/auth/signin', credentials);
    if (response.data.accessToken) {
      localStorage.setItem('token', response.data.accessToken);
    }
    return response.data;
  },
  
  register: async (userData) => {
    return api.post('/auth/signup', userData);
  },
  
  logout: () => {
    localStorage.removeItem('token');
  },
  
   getCurrentUser: async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      // If there's no token, the user is likely not logged in.
      // You can either return null, throw an error, or handle it as needed.
      return null;
    }

    try {
      const response = await api.get('/users/me', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      return response.data;
    } catch (error) {
      // Handle errors, such as invalid token or server errors.
      console.error('Error fetching current user:', error);
      // Optionally, you might want to remove the token from local storage
      // if it's invalid.
      if (error.response && error.response.status === 401) {
          localStorage.removeItem('token');
      }
      return null; // or throw error;
    }
  },
  
  verifyEmail: async (token) => {
    return api.post(`/auth/verify-email/${token}`);
  },
  
  resetPassword: async (email) => {
    return api.post('/auth/reset-password', { email });
  },
  
  confirmResetPassword: async (token, newPassword) => {
    return api.post(`/auth/reset-password/${token}`, { password: newPassword });
  }
};

export default AuthService;