import { createContext, useState, useEffect, useCallback } from 'react';
import { useAuth } from '../hooks/useAuth';
import WalletService from '../services/wallet.service';

export const WalletContext = createContext();

export const WalletProvider = ({ children }) => {
  const { user } = useAuth();
  
  const [wallet, setWallet] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchWallet = useCallback(async () => {
    if (!user) return;
    
    try {
      setLoading(true);
      const response = await WalletService.getWallet();
      setWallet(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to fetch wallet information');
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  const fetchTransactions = useCallback(async (params) => {
    if (!user) return;
    
    try {
      setLoading(true);
      const response = await WalletService.getTransactions(params);
      setTransactions(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to fetch transactions');
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  const deposit = async (amount) => {
    try {
      const response = await WalletService.deposit(amount);
      await fetchWallet();
      return response.data;
    } catch (err) {
      throw err;
    }
  };

  const withdraw = async (amount) => {
    try {
      const response = await WalletService.withdraw(amount);
      await fetchWallet();
      return response.data;
    } catch (err) {
      throw err;
    }
  };

  const transfer = async (recipientWalletNumber, amount, description) => {
    try {
      const response = await WalletService.transfer(recipientWalletNumber, amount, description);
      await fetchWallet();
      return response.data;
    } catch (err) {
      throw err;
    }
  };

  useEffect(() => {
    if (user) {
      fetchWallet();
      fetchTransactions();
    }
  }, [user, fetchWallet, fetchTransactions]);

  const value = {
    wallet,
    transactions,
    loading,
    error,
    fetchWallet,
    fetchTransactions,
    deposit,
    withdraw,
    transfer
  };

  return <WalletContext.Provider value={value}>{children}</WalletContext.Provider>;
};
