import { useState, useEffect, useCallback } from 'react';
import { useAuth } from './useAuth';
import WalletService from '../services/wallet.service';
import { useToast } from './useToast';

export const useWallet = () => {
  const { user } = useAuth();
  const { showToast } = useToast();
  
  const [wallet, setWallet] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchWallet = useCallback(async () => {
    if (!user) return;
    
    try {
      setLoading(true);
      const response = await WalletService.getWallet();
      setWallet(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to fetch wallet information');
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  const fetchTransactions = useCallback(async (params) => {
    if (!user) return;
    
    try {
      setLoading(true);
      const response = await WalletService.getTransactions(params);
      setTransactions(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to fetch transactions');
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  const deposit = useCallback(async (amount) => {
    try {
      const response = await WalletService.deposit(amount);
      await fetchWallet();
      showToast('Deposit successful!', 'success');
      return response.data;
    } catch (err) {
      const message = err.response?.data?.message || 'Failed to process deposit';
      showToast(message, 'error');
      throw err;
    }
  }, [fetchWallet, showToast]);

  const withdraw = useCallback(async (amount) => {
    try {
      const response = await WalletService.withdraw(amount);
      await fetchWallet();
      showToast('Withdrawal successful!', 'success');
      return response.data;
    } catch (err) {
      const message = err.response?.data?.message || 'Failed to process withdrawal';
      showToast(message, 'error');
      throw err;
    }
  }, [fetchWallet, showToast]);

  const transfer = useCallback(async (recipientWalletNumber, amount, description) => {
    try {
      const response = await WalletService.transfer(recipientWalletNumber, amount, description);
      await fetchWallet();
      showToast('Transfer successful!', 'success');
      return response.data;
    } catch (err) {
      const message = err.response?.data?.message || 'Failed to process transfer';
      showToast(message, 'error');
      throw err;
    }
  }, [fetchWallet, showToast]);

  useEffect(() => {
    if (user) {
      fetchWallet();
      fetchTransactions();
    }
  }, [user, fetchWallet, fetchTransactions]);

  return {
    wallet,
    transactions,
    loading,
    error,
    fetchWallet,
    fetchTransactions,
    deposit,
    withdraw,
    transfer
  };
};
